package com.careflow.hospital.scheduling;
import com.careflow.hospital.appointments.*;import com.careflow.hospital.departments.*;import com.careflow.hospital.doctors.*;import com.careflow.hospital.reservations.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class SlotGenerationServiceTest {DepartmentRepository departments=mock(DepartmentRepository.class);DoctorRepository doctors=mock(DoctorRepository.class);DoctorScheduleRepository schedules=mock(DoctorScheduleRepository.class);DoctorScheduleExceptionRepository exceptions=mock(DoctorScheduleExceptionRepository.class);AppointmentRepository appointments=mock(AppointmentRepository.class);SlotReservationRepository reservations=mock(SlotReservationRepository.class);SlotGenerationService service;Department department=mock(Department.class);Doctor doctor=mock(Doctor.class);UUID departmentId=UUID.randomUUID(),doctorId=UUID.randomUUID();LocalDate date=LocalDate.now(ZoneId.of("UTC")).plusDays(1);
 @BeforeEach void setup(){service=new SlotGenerationService(departments,doctors,schedules,exceptions,appointments,reservations);when(department.isActive()).thenReturn(true);when(department.getTimezone()).thenReturn("UTC");when(departments.findById(departmentId)).thenReturn(Optional.of(department));when(doctor.getId()).thenReturn(doctorId);when(doctor.getFullName()).thenReturn("Dr Test");when(doctor.getSpecialization()).thenReturn("General Medicine");when(doctors.findAllByDepartmentIdAndActiveTrueOrderByFullNameAsc(departmentId)).thenReturn(List.of(doctor));when(exceptions.findAllByDoctorIdAndDate(doctorId,date)).thenReturn(List.of());when(appointments.findActiveOverlaps(any(),any(),any())).thenReturn(List.of());when(reservations.findActiveOverlaps(any(),any(),any(),any())).thenReturn(List.of());}
 @Test void expandsScheduleIntoDeterministicSlots(){when(schedules.findAllByDoctorIdAndDayOfWeekAndActiveTrue(doctorId,date.getDayOfWeek().getValue())).thenReturn(List.of(new DoctorSchedule(doctorId,date.getDayOfWeek().getValue(),LocalTime.of(9,0),LocalTime.of(10,0),30)));var result=service.generate(departmentId,null,date);assertEquals(2,result.size());assertEquals(30,result.getFirst().durationMinutes());assertTrue(result.getFirst().startsAt().isBefore(result.getLast().startsAt()));}
 @Test void fullDayExceptionRemovesAllSlots(){when(schedules.findAllByDoctorIdAndDayOfWeekAndActiveTrue(any(),anyInt())).thenReturn(List.of(new DoctorSchedule(doctorId,date.getDayOfWeek().getValue(),LocalTime.of(9,0),LocalTime.of(10,0),30)));when(exceptions.findAllByDoctorIdAndDate(doctorId,date)).thenReturn(List.of(new DoctorScheduleException(doctorId,date,"UNAVAILABLE",null,null,null,"Leave")));assertTrue(service.generate(departmentId,null,date).isEmpty());}
}
